&nbsp;&ndash; <span class=\"italic\">p</span><sup>4</sup>) + (<span class=\"italic\">p</span><sup>5</sup>&nbsp;&ndash; <span class=\"italic\">p</span><sup>5</sup>) + (<span class=\"italic\">p</span><sup>6</sup>&nbsp;&ndash; <span class=\"italic\">p</span><sup>6</sup>) &ndash; <span class=\"italic\">p</span><sup>7</sup>, which can be simplified to 1 &ndash; <span class=\"italic\">p</span><sup>7</sup>.<p><br>Choices A, C, and D are incorrect and may result from incorrectly identifying the highest power of <span class=\"italic\">p</span> in the expressions or incorrectly combining like terms.</p><p>&nbsp;</p></p>\n","answer_style":"Multiple Choice","section":"Math","image_count":5,"raw_list":{"updateDate":1691007959637,"pPcc":"SAT#P","questionId":"3e9cc0c2","skill_cd":"P.A.","score_band_range_cd":5,"skill_desc":"Equivalent expressions","createDate":1691007959637,"program":"SAT","primary_class_cd_desc":"Advanced Math","ibn":"09404-DC","external_id":null,"primary_class_cd":"P","uId":"cadae8a7-8f51-471c-bb42-032a9a5054a9","difficulty":"M"},"raw_detail":{"item_id":"09404-DC","section":"Math","prompt":"<p class=\"stem_paragraph \">Which of the following is equivalent to&nbsp;<span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"\"></span></span> ?</p>\n","answer":{"style":"Multiple Choice","choices":{"a":{"body":"<p class=\"choice_paragraph \"><span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"1 minus p to the power 8\"></span></span></p>\n"},"b":{"body":"<p class=\"choice_paragraph \"><span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"1 minus p to the power 7\"></span></span></p>\n"},"c":{"body":"<p class=\"choice_paragraph \"><span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"1 minus p to the power 6\"></span></span></p>\n"},"d":{"body":"<p class=\"choice_paragraph \"><span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"1 minus p to the power 5\"></span></span></p>\n"}},"correct_choice":"b","rationale":"<p>Choice B is correct. Multiplying (1 &ndash; <span class=\"italic\">p</span>) by each term of the polynomial within the second pair of parentheses gives (1 &ndash; <span class=\"italic\">p</span>)1 = 1 &ndash; <span class=\"italic\">p</span>; (1 &ndash; <span class=\"italic\">p</span>)<span class=\"italic\">p</span> = <span class=\"italic\">p</span> &ndash; <span class=\"italic\">p</span><sup>2</sup>; (1 &ndash; <span class=\"italic\">p</span>)<span class=\"italic\">p</span><sup>2</sup> = <span class=\"italic\">p</span><sup>2</sup> &ndash; <span class=\"italic\">p</span><sup>3</sup>; (1 &ndash; <span class=\"italic\">p</span>)<span class=\"italic\">p</span><sup>3</sup> = <span class=\"italic\">p</span><sup>3</sup> &ndash; <span class=\"italic\">p</span><sup>4</sup>; (1 &ndash; <span class=\"italic\">p</span>)<span class=\"italic\">p</span><sup>4</sup> = <span class=\"italic\">p</span><sup>4</sup> &ndash; <span class=\"italic\">p</span><sup>5</sup>; (1 &ndash; <span class=\"italic\">p</span>)<span class=\"italic\">p</span><sup>5</sup> = <span class=\"italic\">p</span><sup>5</sup> &ndash; <span class=\"italic\">p</span><sup>6</sup>; and (1 &ndash; <span class=\"italic\">p</span>)<span class=\"italic\">p</span><sup>6</sup> = <span class=\"italic\">p</span><sup>6</sup> &ndash; <span class=\"italic\">p</span><sup>7</sup>. Adding these seven expressions together and combining like terms gives&nbsp;1 + (<span class=\"italic\">p</span>&nbsp;&ndash; <span class=\"italic\">p</span>) + (<span class=\"italic\">p</span><span class=\"italic\"><sup>2</sup></span>&nbsp;&ndash; <span class=\"italic\">p</span><sup>2</sup>) + (<span class=\"italic\">p</span><sup>3</sup>&nbsp;&ndash; <span class=\"italic\">p</span><sup>3</sup>) + (<span class=\"italic\">p</span><sup>4</sup>&nbsp;&ndash; <span class=\"italic\">p</span><sup>4</sup>) + (<span class=\"italic\">p</span><sup>5</sup>&nbsp;&ndash; <span class=\"italic\">p</span><sup>5</sup>) + (<span class=\"italic\">p</span><sup>6</sup>&nbsp;&ndash; <span class=\"italic\">p</span><sup>6</sup>) &ndash; <span class=\"italic\">p</span><sup>7</sup>, which can be simplified to 1 &ndash; <span class=\"italic\">p</span><sup>7</sup>.<p><br>Choices A, C, and D are incorrect and may result from incorrectly identifying the highest power of <span class=\"italic\">p</span> in the expressions or incorrectly combining like terms.</p><p>&nbsp;</p></p>\n"}},"createDate":1691007959637,"updateDate":1691007959637}$SATQ$::jsonb, 1691007959637, 1691007959637),
