.55874 3 0.795609 3 0 \nC 3 -0.795609 2.683901 -1.55874 2.12132 -2.12132 \nC 1.55874 -2.683901 0.795609 -3 0 -3 \nC -0.795609 -3 -1.55874 -2.683901 -2.12132 -2.12132 \nC -2.683901 -1.55874 -3 -0.795609 -3 0 \nC -3 0.795609 -2.683901 1.55874 -2.12132 2.12132 \nC -1.55874 2.683901 -0.795609 3 0 3 \nz\n\" id=\"mf0668b9292\" style=\"stroke:#000000;\"></path>\n    </defs>\n    <g clip-path=\"url(#pd1422c4ff4)\">\n     <use style=\"stroke:#000000;\" x=\"152.236178\" xlink:href=\"#mf0668b9292\" y=\"116.340761\"></use>\n    </g>\n   </g>\n   <g id=\"line2d_2\">\n    <path clip-path=\"url(#pd1422c4ff4)\" d=\"M 37.782876 135.118256 \nL 58.387529 134.786142 \nL 73.105138 134.340552 \nL 84.879225 133.766169 \nL 94.550797 133.071284 \nL 102.540356 132.281362 \nL 109.688909 131.351491 \nL 115.996455 130.304435 \nL 121.462996 129.181153 \nL 126.509033 127.926365 \nL 131.134567 126.555491 \nL 135.339599 125.092662 \nL 139.54463 123.388335 \nL 143.329158 121.615139 \nL 147.113686 119.580535 \nL 150.477711 117.521513 \nL 153.841736 115.19477 \nL 156.785257 112.911997 \nL 159.728779 110.371526 \nL 162.672301 107.544266 \nL 165.615823 104.397843 \nL 168.559345 100.896225 \nL 171.502866 96.999315 \nL 174.025885 93.310796 \nL 176.548904 89.268131 \nL 179.071922 84.837319 \nL 181.594941 79.981093 \nL 184.11796 74.658607 \nL 186.640978 68.825095 \nL 189.163997 62.431492 \nL 191.687016 55.424022 \nL 194.210035 47.743745 \nL 196.733053 39.326064 \nL 197.994563 34.818831 \nL 197.994563 34.818831 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n   </g>\n   <g id=\"line2d_3\">\n    <path clip-path=\"url(#pd1422c4ff4)\" d=\"M 131.975574 35.298343 \nL 186.640978 253.959962 \nL 186.640978 253.959962 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n   </g>\n  </g>\n </g>\n <defs>\n  <clipPath id=\"pd1422c4ff4\">\n   <rect height=\"260.82\" width=\"268.898496\" x=\"7.2\" y=\"7.2\"></rect>\n  </clipPath>\n </defs>\n</svg>\n<div role=\"region\" aria-label=\"Long description for graph of a system of a curve and a line\" class=\"sr-only\"><ul><li>For the curve in the system:<br>\n<ul>\n<li>The curve passes from quadrant 2 to quadrant 1.</li>\n<li>In quadrant 2, the curve trends up gradually to the approximate point (0 comma 4.063).</li>\n<li>In quadrant 1:<br>\n<ul>\n<li>The curve trends up gradually to point (4 comma 5).</li>\n<li>The curve then trends up sharply.</li>\n</ul>\n</li>\n<li>The curve passes through the following points:<br>\n<ul>\n<li>(3 comma nine halves)</li>\n<li>(4 comma 5)</li>\n<li>(5 comma 6)</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>For the line in the system:<br>\n<ul>\n<li>The line slants sharply down from left to right.</li>\n<li>The line passes through the following points:<br>\n<ul>\n<li>(3 comma 9)</li>\n<li>(4 comma 5)</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul></div></figure></p>\n<p style=\"text-align: left;\">The graph of a system of a linear equation and a nonlinear equation is shown. What is the solution <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math> to this system?</p>","answerOptions":[{"id":"20ce38df-9366-43f1-b8ec-36b99d5b3b1d","content":"<p><math alttext=\"left parenthesis 0 comma 0 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>0</mn></mrow></mfenced></math></p>"},{"id":"c80f67b4-f507-4a0f-a280-f08d2ab4e206","content":"<p><math alttext=\"left parenthesis 0 comma 4 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>4</mn></mrow></mfenced></math></p>"},{"id":"911bdc31-5c1e-41ab-a19f-067b130a6f79","content":"<p><math alttext=\"left parenthesis 4 comma 5 right parenthesis\"><mfenced><mrow><mn>4</mn><mo>,</mo><mn>5</mn></mrow></mfenced></math></p>"},{"id":"c380b84b-9eaf-4c05-954c-4f2bf7bb0c5b","content":"<p><math alttext=\"left parenthesis 5 comma 0 right parenthesis\"><mfenced><mrow><mn>5</mn><mo>,</mo><mn>0</mn></mrow></mfenced></math></p>"}],"keys":["911bdc31-5c1e-41ab-a19f-067b130a6f79"],"correct_answer":["C"],"rationale":"<p style=\"text-align: left;\">Choice C is correct. The solution to the system of two equations corresponds to the point where the graphs of the equations intersect. The graphs of the linear equation and the nonlinear equation shown intersect at the point <math alttext=\"left parenthesis 4 comma 5 right parenthesis\"><mfenced><mrow><mn>4</mn><mo>,</mo><mn>5</mn></mrow></mfenced></math>. Thus, the solution to the system is <math alttext=\"left parenthesis 4 comma 5 right parenthesis\"><mfenced><mrow><mn>4</mn><mo>,</mo><mn>5</mn></mrow></mfenced></math>.</p>\n<p style=\"text-align: left;\">Choice A is incorrect and may result from conceptual or calculation errors.</p>\n<p style=\"text-align: left;\">Choice B is incorrect and may result from conceptual or calculation errors.</p>\n<p style=\"text-align: left;\">Choice D is incorrect and may result from conceptual or calculation errors.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"image_count":0,"raw_list":{"updateDate":1730147357397,"pPcc":"SAT#P","questionId":"3f8d5876","skill_cd":"P.B.","score_band_range_cd":1,"skill_desc":"Nonlinear equations in one variable and systems of equations in two variables ","createDate":1730147357397,"program":"SAT","primary_class_cd_desc":"Advanced Math","ibn":"","external_id":"39a54602-89bd-4494-9358-17d9877e73da","primary_class_cd":"P","uId":"7075be7c-d21d-498b-aa70-57f93e875304","difficulty":"E"},"raw_detail":{"answerOptions":[{"content":"<p><math alttext=\"left parenthesis 0 comma 0 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>0</mn></mrow></mfenced></math></p>","id":"20ce38df-9366-43f1-b8ec-36b99d5b3b1d"},{"content":"<p><math alttext=\"left parenthesis 0 comma 4 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>4</mn></mrow></mfenced></math></p>","id":"c80f67b4-f507-4a0f-a280-f08d2ab4e206"},{"co