i>x</mi>\n\t\t\t</mrow>\n\t\t\t<mo>-</mo>\n\t\t\t<mn>6</mn>\n\t\t</mrow>\n\t</mfrac>\n</mrow>\n</math></p>"},{"id":"3bb4230d-84b1-4efc-a821-b8f42dbfa30e","content":"<p><math alttext=\"minus StartFraction 1 Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mrow>\n\t<mo>-</mo>\n\t<mfrac>\n\t\t<mn>1</mn>\n\t\t<mrow>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t<mo>+</mo>\n\t\t\t\t\t<mn>1</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mrow>\n\t\t\t\t\t\t<mn>4</mn>\n\t\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t</mrow>\n\t\t\t\t\t<mo>-</mo>\n\t\t\t\t\t<mn>5</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t</mrow>\n\t</mfrac>\n</mrow>\n</math></p>"},{"id":"70219617-b3ce-40b5-8322-d737af0f393e","content":"<p><math alttext=\"StartFraction 9 Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mrow>\n\t<mfrac>\n\t\t<mn>9</mn>\n\t\t<mrow>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t<mo>+</mo>\n\t\t\t\t\t<mn>1</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mrow>\n\t\t\t\t\t\t<mn>4</mn>\n\t\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t</mrow>\n\t\t\t\t\t<mo>-</mo>\n\t\t\t\t\t<mn>5</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t</mrow>\n\t</mfrac>\n</mrow>\n</math></p>"}],"keys":["70219617-b3ce-40b5-8322-d737af0f393e"],"correct_answer":["D"],"rationale":"<p>Choice D is correct. The expression&nbsp;<math alttext=\"StartFraction 4 Over 4 x minus 5 EndFraction minus StartFraction 1 Over x plus 1 EndFraction\"><mfrac><mn>4</mn><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac><mo>-</mo><mfrac><mn>1</mn><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac></math> can be rewritten as&nbsp;<math alttext=\"StartFraction 4 Over 4 x minus 5 EndFraction plus StartFraction left parenthesis negative 1 right parenthesis Over x plus 1 EndFraction\"><mfrac><mn>4</mn><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac><mo>+</mo><mfrac><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac></math>. To add the two terms of this expression, the terms can be rewritten with a common denominator. Since <math alttext=\"StartFraction x plus 1 Over x plus 1 EndFraction equals 1\"><mfrac><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac><mo>=</mo><mn>1</mn></math>, the expression <math alttext=\"StartFraction 4 Over 4 x minus 5 EndFraction\"><mfrac><mn>4</mn><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac></math> can be rewritten as <math alttext=\"StartFraction left parenthesis x plus 1 right parenthesis left parenthesis 4 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mn>4</mn></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>. Since <math alttext=\"StartFraction 4 x minus 5 Over 4 x minus 5 EndFraction equals 1\"><mfrac><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac><mo>=</mo><mn>1</mn></math>, the expression <math alttext=\"StartFraction negative 1 Over x plus 1 EndFraction\"><mfrac><mrow><mo>-</mo><mn>1</mn></mrow><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac></math> can be rewritten as <math alttext=\"StartFraction left parenthesis 4 x minus 5 right parenthesis left parenthesis negative 1 right parenthesis Over left parenthesis 4 x minus 5 right parenthesis left parenthesis x plus 1 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced></mrow></mfrac></math>. Therefore, the expression&nbsp;<math alttext=\"StartFraction 4 Over 4 x minus 5 EndFraction plus StartFraction left parenthesis negative 1 right parenthesis Over x plus 1 EndFraction\"><mfrac><mn>4</mn><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac><mo>+</mo><mfrac><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac></math> can be rewritten as&nbsp;<math alttext=\"StartFraction left parenthesis x plus 1 right parenthesis left parenthesis 4 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction plus StartFraction left parenthesis 4 x minus 5 right parenthesis left parenthesis negative 1 right parenthesis Over left parenthesis 4 x minus 5 right parenthesis left parenthesis x plus 1 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mn>4</mn></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac><mo>+</mo><mfrac><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced></mrow></mfrac></math>, which is equivalent to <math alttext=\"StartFraction left parenthesis x plus 1 right parenthesis left parenthesis 4 right parenthesis plus left parenthesis 4 x minus 5 right parenthesis left parenthesis negative 1 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mn>4</mn></mfenced><mo>+</mo><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>.&nbsp;Applying the distributive property to each term of the numerator yields <math alttext=\"StartFraction left parenthesis 4 x plus 4 right parenthesis plus left parenthesis minus 4 x plus 5 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>+</mo><mn>4</mn></mrow></mfenced><mo>+</mo><mfenced><mrow><mo>-</mo><mn>4</mn><mi>x</mi><mo>+</mo><mn>5</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>, or&nbsp; <math alttext=\"StartFraction left parenthesis 4 x plus left parenthesis minus 4 x right parenthesis right parenthesis plus left parenthesis 4 plus 5 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>+</mo><mfenced><mrow><mo>-</mo><mn>4</mn><mi>x</mi></mrow></mfenced></mrow></mfenced><mo>+</mo><mfenced><mrow><mn>4</mn><mo>+</mo><mn>5</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>. Adding like terms in the numerator yields&nbsp;<math alttext=\"StartFraction 9 Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mn>9</mn><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>.</p>\n<p>Choice A is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice B is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice C is incorrect and may result from conceptual or calculation errors.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":"manifold","position":null,"image_count":0,"raw_list":{"updateDate":1691007959821,"pPcc":"SAT#P","questionId":"433184f1","skill_cd":"P.A.","score_band_range_cd":6,"skill_desc":"Equivalent expressions","createDate":1691007959821,"program":"SAT","primary_class_cd_desc":"Advanced Math","ibn":null,"external_id":"16d897b1-c597-4b7a-b4ee-ecba3515085e","primary_class_cd":"P","uId":"307d3be2-c903-4943-8e6c-d5cb417992cd","difficulty":"H"},"raw_detail":{"keys":["70219617-b3ce-40b5-8322-d737af0f393e"],"rationale":"<p>Choice D is correct. The expression&nbsp;<math alttext=\"StartFraction 4 Over 4 x minus 5 EndFraction minus StartFraction 1 Over x plus 1 EndFraction\"><mfrac><mn>4</mn><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac><mo>-</mo><mfrac><mn>1</mn><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac></math> can be rewritten as&nbsp;<math alttext=\"StartFraction 4 Over 4 x minus 5 EndFraction plus StartFraction left parenthesis negative 1 right parenthesis Over x plus 1 EndFraction\"><mfrac><mn>4</mn><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac><mo>+</mo><mfrac><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac></math>. To add the two terms of this expression, the terms can be rewritten with a common denominator. Since <math alttext=\"StartFraction x plus 1 Over x plus 1 EndFraction equals 1\"><mfrac><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac><mo>=</mo><mn>1</mn></math>, the expression <math alttext=\"StartFraction 4 Over 4 x minus 5 EndFraction\"><mfrac><mn>4</mn><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac></math> can be rewritten as <math alttext=\"StartFraction left parenthesis x plus 1 right parenthesis left parenthesis 4 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mn>4</mn></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>. Since <math alttext=\"StartFraction 4 x minus 5 Over 4 x minus 5 EndFraction equals 1\"><mfrac><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac><mo>=</mo><mn>1</mn></math>, the expression <math alttext=\"StartFraction negative 1 Over x plus 1 EndFraction\"><mfrac><mrow><mo>-</mo><mn>1</mn></mrow><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac></math> can be rewritten as <math alttext=\"StartFraction left parenthesis 4 x minus 5 right parenthesis left parenthesis negative 1 right parenthesis Over left parenthesis 4 x minus 5 right parenthesis left parenthesis x plus 1 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced></mrow></mfrac></math>. Therefore, the expression&nbsp;<math alttext=\"StartFraction 4 Over 4 x minus 5 EndFraction plus StartFraction left parenthesis negative 1 right parenthesis Over x plus 1 EndFraction\"><mfrac><mn>4</mn><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfrac><mo>+</mo><mfrac><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfrac></math> can be rewritten as&nbsp;<math alttext=\"StartFraction left parenthesis x plus 1 right parenthesis left parenthesis 4 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction plus StartFraction left parenthesis 4 x minus 5 right parenthesis left parenthesis negative 1 right parenthesis Over left parenthesis 4 x minus 5 right parenthesis left parenthesis x plus 1 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mn>4</mn></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac><mo>+</mo><mfrac><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced></mrow></mfrac></math>, which is equivalent to <math alttext=\"StartFraction left parenthesis x plus 1 right parenthesis left parenthesis 4 right parenthesis plus left parenthesis 4 x minus 5 right parenthesis left parenthesis negative 1 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mn>4</mn></mfenced><mo>+</mo><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced><mfenced><mrow><mo>-</mo><mn>1</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>.&nbsp;Applying the distributive property to each term of the numerator yields <math alttext=\"StartFraction left parenthesis 4 x plus 4 right parenthesis plus left parenthesis minus 4 x plus 5 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>+</mo><mn>4</mn></mrow></mfenced><mo>+</mo><mfenced><mrow><mo>-</mo><mn>4</mn><mi>x</mi><mo>+</mo><mn>5</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>, or&nbsp; <math alttext=\"StartFraction left parenthesis 4 x plus left parenthesis minus 4 x right parenthesis right parenthesis plus left parenthesis 4 plus 5 right parenthesis Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mrow><mfenced><mrow><mn>4</mn><mi>x</mi><mo>+</mo><mfenced><mrow><mo>-</mo><mn>4</mn><mi>x</mi></mrow></mfenced></mrow></mfenced><mo>+</mo><mfenced><mrow><mn>4</mn><mo>+</mo><mn>5</mn></mrow></mfenced></mrow><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>. Adding like terms in the numerator yields&nbsp;<math alttext=\"StartFraction 9 Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mfrac><mn>9</mn><mrow><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced><mfenced><mrow><mn>4</mn><mi>x</mi><mo>-</mo><mn>5</mn></mrow></mfenced></mrow></mfrac></math>.</p>\n<p>Choice A is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice B is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice C is incorrect and may result from conceptual or calculation errors.</p>","origin":"manifold","stem":"<p>Which expression is equivalent to <math alttext=\"StartFraction 4 Over 4 x minus 5 EndFraction minus StartFraction 1 Over x plus 1 EndFraction\"><mrow>\n\t<mrow>\n\t\t<mfrac>\n\t\t\t<mn>4</mn>\n\t\t\t<mrow>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mn>4</mn>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t</mrow>\n\t\t\t\t<mo>-</mo>\n\t\t\t\t<mn>5</mn>\n\t\t\t</mrow>\n\t\t</mfrac>\n\t</mrow>\n\t<mo>-</mo>\n\t<mfrac>\n\t\t<mn>1</mn>\n\t\t<mrow>\n\t\t\t<mi>x</mi>\n\t\t\t<mo>+</mo>\n\t\t\t<mn>1</mn>\n\t\t</mrow>\n\t</mfrac>\n</mrow>\n</math>?</p>","externalid":"16d897b1-c597-4b7a-b4ee-ecba3515085e","templateid":"ec0ad03b-1b26-4099-8db8-720fe45dcb43","vaultid":"760627be-5e15-4e54-9b8c-9a4d8a0d557c","type":"mcq","answerOptions":[{"id":"533168fc-e254-4688-9120-40c5d7735a25","content":"<p><math alttext=\"StartFraction 1 Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mrow>\n\t<mfrac>\n\t\t<mn>1</mn>\n\t\t<mrow>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t<mo>+</mo>\n\t\t\t\t\t<mn>1</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mrow>\n\t\t\t\t\t\t<mn>4</mn>\n\t\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t</mrow>\n\t\t\t\t\t<mo>-</mo>\n\t\t\t\t\t<mn>5</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t</mrow>\n\t</mfrac>\n</mrow>\n</math></p>"},{"id":"6e7aff63-7d47-419c-9e69-cb9ce7b1f65e","content":"<p><math alttext=\"StartFraction 3 Over 3 x minus 6 EndFraction\"><mrow>\n\t<mfrac>\n\t\t<mn>3</mn>\n\t\t<mrow>\n\t\t\t<mrow>\n\t\t\t\t<mn>3</mn>\n\t\t\t\t<mi>x</mi>\n\t\t\t</mrow>\n\t\t\t<mo>-</mo>\n\t\t\t<mn>6</mn>\n\t\t</mrow>\n\t</mfrac>\n</mrow>\n</math></p>"},{"id":"3bb4230d-84b1-4efc-a821-b8f42dbfa30e","content":"<p><math alttext=\"minus StartFraction 1 Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mrow>\n\t<mo>-</mo>\n\t<mfrac>\n\t\t<mn>1</mn>\n\t\t<mrow>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t<mo>+</mo>\n\t\t\t\t\t<mn>1</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mrow>\n\t\t\t\t\t\t<mn>4</mn>\n\t\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t</mrow>\n\t\t\t\t\t<mo>-</mo>\n\t\t\t\t\t<mn>5</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t</mrow>\n\t</mfrac>\n</mrow>\n</math></p>"},{"id":"70219617-b3ce-40b5-8322-d737af0f393e","content":"<p><math alttext=\"StartFraction 9 Over left parenthesis x plus 1 right parenthesis left parenthesis 4 x minus 5 right parenthesis EndFraction\"><mrow>\n\t<mfrac>\n\t\t<mn>9</mn>\n\t\t<mrow>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t<mo>+</mo>\n\t\t\t\t\t<mn>1</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t\t<mfenced>\n\t\t\t\t<mrow>\n\t\t\t\t\t<mrow>\n\t\t\t\t\t\t<mn>4</mn>\n\t\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t</mrow>\n\t\t\t\t\t<mo>-</mo>\n\t\t\t\t\t<mn>5</mn>\n\t\t\t\t</mrow>\n\t\t\t</mfenced>\n\t\t</mrow>\n\t</mfrac>\n</mrow>\n</math></p>"}],"correct_answer":["D"]},"createDate":1691007959821,"updateDate":1691007959821}$SATQ$::jsonb, 1691007959821, 1691007959821),
    ($SATQ$43926bd9$SATQ$, NULL, NULL, $SATQ$029650-DC$SATQ$, $SATQ$disclosed$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.C.$SATQ$, $SATQ$Nonlinear functions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$spr$SATQ$, $SATQ$<div class="stimulus_reference " xmlns="http://www.imsglobal.org/xsd/apip/apipv1p0/qtiitem/imsqti_v2p1"><div class="table_wrapper "><div class="tcp-62e5f992-f673-40bd-a548-202c834d3ad3"><table class="table_WithBorder tcp-ef7929fc-9906-4a23-8e76-a522e192eb90"><tbody><tr><td class="tcp-02ed6c46-bd1e-4259-860e-081d51202b23"><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_000_e8247862.png" alt="x"></span></td><td class="tcp-35ddec34-fbac-495c-ae5b-76f7f7ffab61"><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_001_09ff893b.png" alt="f of x"></span></td></tr><tr><td class="tcp-f28a9eef-359b-45a0-ade4-7c644d87bb6d"><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_002_259db25f.png" alt="1"></span></td><td class="tcp-775e061f-847b-43ac-97d4-24f063c3ebf2"><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_003_6253433b.png" alt="a"></span></td></tr><tr><td class="tcp-affd227e-10e3-4509-bf76-780708dbf2d4"><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_004_27137981.png" alt="2"></span></td><td class="tcp-68d1a00e-9736-470d-bffd-824d15d89e0c"><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_005_a49c5f4d.png" alt="a, to the fifth power."></span></td></tr><tr><td class="tcp-551cd67d-94b3-42f2-94be-c2adb50ceaf5"><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_006_9db9796b.png" alt="3"></span></td><td class="tcp-4b64f365-e12d-4426-abc5-371a88be077a"><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_007_68b6c8ec.png" alt="a, to the ninth power"></span></td></tr></tbody></table></div><p><br>For the exponential function <span class="italic">f</span>, the table above shows several values of <span class="italic">x</span> and their corresponding values of <span class="math_expression "><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_008_175381e2.png" alt="f of x"></span></span>, where <span class="italic">a</span> is a constant greater than 1. If <span class="italic">k</span> is a constant and <span class="math_expression "><span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_009_d535bcc4.png" alt="f of k, equals a, to the twenty ninth power"></span></span>, what is the value of <span class="italic">k </span>?</p></div></div>
$SATQ$, $SATQ$$SATQ$, NULL, $SATQ$["8"]$SATQ$::jsonb, NULL, $SATQ$<p>The correct answer is 8. The values of <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_010_175381e2.png" alt="f of x "></span> for the exponential function <span class="italic">f</span> shown in the table increase by a factor of <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_011_739aa48d.png" alt="a, to the fourth power "></span> for each increase of 1 in <span class="italic">x</span>. This relationship can be represented by the equation <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_012_ba9002b4.png" alt="f of x equals, a, raised to the 4 x plus b power"></span>, where <span class="italic">b</span> is a constant. It&rsquo;s given that when <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_013_4a24f52d.png" alt="x equals 2"></span>, <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_014_283aced2.png" alt="f of x equals, a, to the fifth power"></span>.&nbsp; Substituting 2 for <span class="italic">x</span> and <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_015_a49c5f4d.png" alt="a, to the fifth power"></span> for <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_016_175381e2.png" alt="f of x "></span> into <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_017_ba9002b4.png" alt="f of x equals, a, raised to the 4 x plus b power  "></span> yields <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_018_2331cf43.png" alt="a, to the fifth power equals, a, raised to the 4 times 2, plus b power"></span>. Since <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_019_fbafab65.png" alt="4 times 2, plus b, equals 5"></span>, it follows that <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_020_18325c0e.png" alt="b equals negative 3"></span>. Thus, an equation that defines the function <span class="italic">f</span> is <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_021_2b017679.png" alt="f of x equals, a, raised to the 4 x minus 3 power"></span>. It follows that the value of <span class="italic">k</span> such that <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_022_bfbf9b1e.png" alt="f of k equals, a, to the twenty ninth power"></span> can be found by solving the equation <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_023_28df1cc1.png" alt="4 k minus 3, equals 29"></span>, which yields <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_024_d7720799.png" alt="k equals 8"></span>.</p>
