jrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_004_27137981.png\" alt=\"2\"></span></td><td class=\"tcp-68d1a00e-9736-470d-bffd-824d15d89e0c\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_005_a49c5f4d.png\" alt=\"a, to the fifth power.\"></span></td></tr><tr><td class=\"tcp-551cd67d-94b3-42f2-94be-c2adb50ceaf5\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_006_9db9796b.png\" alt=\"3\"></span></td><td class=\"tcp-4b64f365-e12d-4426-abc5-371a88be077a\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_007_68b6c8ec.png\" alt=\"a, to the ninth power\"></span></td></tr></tbody></table></div><p><br>For the exponential function <span class=\"italic\">f</span>, the table above shows several values of <span class=\"italic\">x</span> and their corresponding values of <span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_008_175381e2.png\" alt=\"f of x\"></span></span>, where <span class=\"italic\">a</span> is a constant greater than 1. If <span class=\"italic\">k</span> is a constant and <span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_009_d535bcc4.png\" alt=\"f of k, equals a, to the twenty ninth power\"></span></span>, what is the value of <span class=\"italic\">k </span>?</p></div></div>\n","stem":"","answerOptions":null,"keys":null,"correct_answer":["8"],"rationale":"<p>The correct answer is 8. The values of <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_010_175381e2.png\" alt=\"f of x \"></span> for the exponential function <span class=\"italic\">f</span> shown in the table increase by a factor of <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_011_739aa48d.png\" alt=\"a, to the fourth power \"></span> for each increase of 1 in <span class=\"italic\">x</span>. This relationship can be represented by the equation <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_012_ba9002b4.png\" alt=\"f of x equals, a, raised to the 4 x plus b power\"></span>, where <span class=\"italic\">b</span> is a constant. It&rsquo;s given that when <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_013_4a24f52d.png\" alt=\"x equals 2\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_014_283aced2.png\" alt=\"f of x equals, a, to the fifth power\"></span>.&nbsp; Substituting 2 for <span class=\"italic\">x</span> and <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_015_a49c5f4d.png\" alt=\"a, to the fifth power\"></span> for <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_016_175381e2.png\" alt=\"f of x \"></span> into <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_017_ba9002b4.png\" alt=\"f of x equals, a, raised to the 4 x plus b power  \"></span> yields <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_018_2331cf43.png\" alt=\"a, to the fifth power equals, a, raised to the 4 times 2, plus b power\"></span>. Since <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_019_fbafab65.png\" alt=\"4 times 2, plus b, equals 5\"></span>, it follows that <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_020_18325c0e.png\" alt=\"b equals negative 3\"></span>. Thus, an equation that defines the function <span class=\"italic\">f</span> is <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_021_2b017679.png\" alt=\"f of x equals, a, raised to the 4 x minus 3 power\"></span>. It follows that the value of <span class=\"italic\">k</span> such that <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_022_bfbf9b1e.png\" alt=\"f of k equals, a, to the twenty ninth power\"></span> can be found by solving the equation <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_023_28df1cc1.png\" alt=\"4 k minus 3, equals 29\"></span>, which yields <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/43926bd9/img_024_d7720799.png\" alt=\"k equals 8\"></span>.</p>\n","answer_style":"SPR","section":"Math","image_count":25,"raw_list":{"updateDate":1691007959626,"pPcc":"SAT#P","questionId":"43926bd9","skill_cd":"P.C.","score_band_range_cd":6,"skill_desc":"Nonlinear functions","createDate":1691007959626,"program":"SAT","primary_class_cd_desc":"Advanced Math","ibn":"029650-DC","external_id":null,"primary_class_cd":"P","uId":"ea166a5e-c813-4109-85fa-700fdc50edf9","difficulty":"H"},"raw_detail":{"item_id":"029650-DC","section":"Math","body":"<div class=\"stimulus_reference \" xmlns=\"http://www.imsglobal.org/xsd/apip/apipv1p0/qtiitem/imsqti_v2p1\"><div class=\"table_wrapper \"><div class=\"tcp-62e5f992-f673-40bd-a548-202c834d3ad3\"><table class=\"table_WithBorder tcp-ef7929fc-9906-4a23-8e76-a522e192eb90\"><tbody><tr><td class=\"tcp-02ed6c46-bd1e-4259-860e-081d51202b23\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"x\"></span></td><td class=\"tcp-35ddec34-fbac-495c-ae5b-76f7f7ffab61\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of x\"></span></td></tr><tr><td class=\"tcp-f28a9eef-359b-45a0-ade4-7c644d87bb6d\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAYCAYAAADDLGwtAAAACXBIWXMAAA7EAAAOxAGVKw4bAAAABGJhU0UAAAAMyZLetQAAADpJREFUeNpjYECAFiDeBsTPgfg/lI8VfAHiY0A8lZBCJiQ2XoUMowrxKQxBwiCFa5D4GKbgwqNgBAEAJqId2Z1H3qYAAAAASUVORK5CYII=\" alt=\"1\"></span></td><td class=\"tcp-775e061f-847b-43ac-97d4-24f063c3ebf2\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"a\"></span></td></tr><tr><td class=\"tcp-affd227e-10e3-4509-bf76-780708dbf2d4\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"2\"></span></td><td class=\"tcp-68d1a00e-9736-470d-bffd-824d15d89e0c\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"a, to the fifth power.\"></span></td></tr><tr><td class=\"tcp-551cd67d-94b3-42f2-94be-c2adb50ceaf5\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"3\"></span></td><td class=\"tcp-4b64f365-e12d-4426-abc5-371a88be077a\"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"a, to the ninth power\"></span></td></tr></tbody></table></div><p><br>For the exponential function <span class=\"italic\">f</span>, the table above shows several values of <span class=\"italic\">x</span> and their corresponding values of <span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of x\"></span></span>, where <span class=\"italic\">a</span> is a constant greater than 1. If <span class=\"italic\">k</span> is a constant and <span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of k, equals a, to the twenty ninth power\"></span></span>, what is the value of <span class=\"italic\">k </span>?</p></div></div>\n","answer":{"style":"SPR","rationale":"<p>The correct answer is 8. The values of <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of x \"></span> for the exponential function <span class=\"italic\">f</span> shown in the table increase by a factor of <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"a, to the fourth power \"></span> for each increase of 1 in <span class=\"italic\">x</span>. This relationship can be represented by the equation <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of x equals, a, raised to the 4 x plus b power\"></span>, where <span class=\"italic\">b</span> is a constant. It&rsquo;s given that when <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"x equals 2\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of x equals, a, to the fifth power\"></span>.&nbsp; Substituting 2 for <span class=\"italic\">x</span> and <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"a, to the fifth power\"></span> for <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of x \"></span> into <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of x equals, a, raised to the 4 x plus b power  \"></span> yields <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"a, to the fifth power equals, a, raised to the 4 times 2, plus b power\"></span>. Since <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"4 times 2, plus b, equals 5\"></span>, it follows that <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"b equals negative 3\"></span>. Thus, an equation that defines the function <span class=\"italic\">f</span> is <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of x equals, a, raised to the 4 x minus 3 power\"></span>. It follows that the value of <span class=\"italic\">k</span> such that <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"f of k equals, a, to the twenty ninth power\"></span> can be found by solving the equation <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"4 k minus 3, equals 29\"></span>, which yields <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k equals 8\"></span>.</p>\n"}},"createDate":1691007959626,"updateDate":1691007959626,"correct_answer_extracted_from_rationale":true}$SATQ$::jsonb, 1691007959626, 1691007959626),
